import React, { useContext, useEffect, useState } from 'react';
import { Alert, Form, Spinner } from 'react-bootstrap';
import { FaArrowLeft, FaCalendarCheck, FaSearch, FaSyncAlt } from 'react-icons/fa';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../../App';
import Layout from '../common/Layout';
import {
  fetchStudentAttendance,
  fetchStudentYearlyAttendance,
  updateStudentAttendance,
} from '../../services/AttendanceServices/attendanceServices';
import {
  fetchBranchClasses,
  fetchClassSections,
} from '../../services/HomeworkServices/homeworkServices';

const attendanceOptions = [
  { value: 'FIRSTHALF', label: 'First half' },
  { value: 'ABSENT', label: 'Absent' },
  { value: 'FULLDAY', label: 'Full day' },
];

const statusFromPeriods = (periods = '') => {
  if (periods === '1-1-1-1-0-0-0-0') return 'FIRSTHALF';
  if (periods === '0-0-0-0-0-0-0-0') return 'ABSENT';
  if (periods === '1-1-1-1-1-1-1-1') return 'FULLDAY';
  return '';
};

const MONTH_NAMES = {
  Jan: 'January', Feb: 'February', Mar: 'March', Apr: 'April',
  May: 'May', Jun: 'June', Jul: 'July', Aug: 'August',
  Sep: 'September', Oct: 'October', Nov: 'November', Dec: 'December',
};

const countMonth = (month) => {
  const key = Object.keys(MONTH_NAMES).find((item) => Object.prototype.hasOwnProperty.call(month, item));
  const days = key && month[key] ? month[key].split('#').filter(Boolean) : [];
  const present = days.filter((status) => status === '1').length;
  const absent = Number(month?.abscnt) || 0;
  return { key, present, absent, total: present + absent };
};

function StudentAttendanceSummary() {
  const { stateAuth } = useContext(AuthContext);
  const user = stateAuth?.user || {};
  const navigate = useNavigate();
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);
  const [alert, setAlert] = useState(null);

  const loadSummary = async () => {
    setLoading(true);
    setAlert(null);
    try {
      const response = await fetchStudentYearlyAttendance({
        typ: 'STUDENT',
        utype: 'STUDENT',
        utyp: 'student',
        usrid: user.usrid,
        stdid: user.stdid,
        instid: user.instid,
        brcid: user.brcid,
        acdmcyr: user.acdmcyr,
      });
      if (response?.status !== 'success') {
        throw new Error(response?.error?.message || 'Failed to fetch attendance.');
      }
      const payload = Array.isArray(response.payload) ? response.payload[0] : response.payload;
      setSummary(payload || { stdnm: user.stdnm, year: [] });
    } catch (error) {
      setAlert(error.message || 'Failed to fetch attendance.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadSummary(); }, [user.stdid, user.acdmcyr]); // eslint-disable-line react-hooks/exhaustive-deps

  const months = Array.isArray(summary?.year) ? summary.year : [];
  const totals = months.reduce((result, month) => {
    const count = countMonth(month);
    result.present += count.present;
    result.absent += count.absent;
    result.total += count.total;
    return result;
  }, { present: 0, absent: 0, total: 0 });
  const percentage = totals.total ? Math.round((totals.present / totals.total) * 100) : 0;

  return (
    <Layout>
      <div className="attendance-page student-attendance-summary">
        <div className="attendance-shell">
          <header className="attendance-header">
            <button className="hw-icon-btn" type="button" onClick={() => navigate('/dashboard')} aria-label="Go back"><FaArrowLeft /></button>
            <div><span className="hw-kicker">Academic year {user.acdmcyr || ''}</span><h1>My Attendance</h1><p>All-month attendance summary</p></div>
            <button className="hw-icon-btn attendance-refresh" type="button" onClick={loadSummary} disabled={loading} aria-label="Refresh"><FaSyncAlt /></button>
          </header>

          {alert && <Alert variant="danger">{alert}</Alert>}
          {loading ? <div className="hw-loading"><Spinner animation="border" size="sm" /> Loading attendance...</div> : (
            <>
              <section className="attendance-overview">
                <div className="attendance-percentage"><strong>{percentage}%</strong><span>Overall attendance</span></div>
                <div><strong>{totals.present}</strong><span>Present</span></div>
                <div><strong>{totals.absent}</strong><span>Absent</span></div>
              </section>
              <section className="attendance-month-grid">
                {months.map((month) => {
                  const count = countMonth(month);
                  const monthPercentage = count.total ? Math.round((count.present / count.total) * 100) : 0;
                  return <article className="attendance-month-card" key={count.key}>
                    <div><strong>{MONTH_NAMES[count.key] || count.key}</strong><span>{monthPercentage}%</span></div>
                    <div className="attendance-progress"><span style={{ width: `${monthPercentage}%` }} /></div>
                    <p><span>{count.present} present</span><span>{count.absent} absent</span></p>
                  </article>;
                })}
                {!months.length && <div className="hw-empty">No attendance records found for this academic year.</div>}
              </section>
            </>
          )}
        </div>
      </div>
    </Layout>
  );
}

function StaffAttendancePage() {
  const { stateAuth } = useContext(AuthContext);
  const user = stateAuth?.user || {};
  const navigate = useNavigate();
  const [classes, setClasses] = useState([]);
  const [sections, setSections] = useState([]);
  const [classId, setClassId] = useState('');
  const [sectionId, setSectionId] = useState('');
  const [hasSearched, setHasSearched] = useState(false);
  const [students, setStudents] = useState([]);
  const [statuses, setStatuses] = useState({});
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [alert, setAlert] = useState(null);

  const loadAttendance = async () => {
    if (!classId || !sectionId) {
      setAlert({ variant: 'danger', message: 'Please select class and section.' });
      return;
    }
    setLoading(true);
    setAlert(null);
    const response = await fetchStudentAttendance({
      typ: 'STUDENT',
      instid: user.instid,
      brcid: user.brcid,
      acdmcyr: user.acdmcyr,
      cls: classId,
      sec: sectionId,
      utype: 'STUDENT',
    });
    setLoading(false);
    setHasSearched(true);

    if (response?.status !== 'success') {
      setAlert({ variant: 'danger', message: response?.error?.message || 'Failed to fetch attendance.' });
      return;
    }

    const rows = Array.isArray(response.payload) ? response.payload : [];
    setStudents(rows);
    setStatuses(Object.fromEntries(rows.map((row) => [row.stdid, statusFromPeriods(row.prds)])));
  };

  useEffect(() => {
    if (!user.brcid || !user.acdmcyr) return;
    fetchBranchClasses({ brcid: user.brcid, acdmcyr: user.acdmcyr }).then((response) => {
      if (response?.status === 'success') setClasses(response.payload || []);
    });
  }, [user.brcid, user.acdmcyr]);

  const handleClassChange = async (event) => {
    const value = event.target.value;
    setClassId(value);
    setSectionId('');
    setSections([]);
    setStudents([]);
    setStatuses({});
    setHasSearched(false);
    setAlert(null);
    if (!value) return;
    const response = await fetchClassSections({ clsid: value });
    if (response?.status === 'success') setSections(response.payload || []);
  };

  const handleSectionChange = (event) => {
    setSectionId(event.target.value);
    setStudents([]);
    setStatuses({});
    setHasSearched(false);
    setAlert(null);
  };

  const saveAttendance = async () => {
    if (!students.length) return;
    if (students.some((student) => !statuses[student.stdid])) {
      setAlert({ variant: 'danger', message: 'Please select attendance for every student.' });
      return;
    }
    setSaving(true);
    setAlert(null);

    const response = await updateStudentAttendance({
      updby: user.usrid,
      periods: students.map((student) => ({
        atndncid: student.atndncid,
        stdid: student.stdid,
        fkinstid: student.fkinstid,
        fkbrcid: student.fkbrcid,
        cls: student.cls,
        sec: student.sec,
        acdmcyr: student.acdmcyr || user.acdmcyr,
        prds: student.prds || '1-1-1-1-1-1-1-1',
        dys: statuses[student.stdid],
        typ: 'STUDENT',
        strdt: student.strdt,
        utyp: 'student',
      })),
    });
    setSaving(false);

    if (response?.status === 'success') {
      const updateResults = Array.isArray(response.payload)
        ? response.payload
        : [];
      const failed = updateResults.filter((item) => item?.status === false);
      setAlert({
        variant: failed.length ? 'warning' : 'success',
        message: failed.length
          ? failed.map((item) => `${item.stdid}: ${item.message}`).join(', ')
          : response.payload?.message || 'Attendance updated successfully.',
      });
      if (!failed.length) loadAttendance();
    } else {
      setAlert({ variant: 'danger', message: response?.error?.message || 'Failed to update attendance.' });
    }
  };

  return (
    <Layout>
      <div className="attendance-page">
        <div className="attendance-shell">
          <header className="attendance-header">
            <button className="hw-icon-btn" type="button" onClick={() => navigate('/dashboard')} aria-label="Go back">
              <FaArrowLeft />
            </button>
            <div>
              <span className="hw-kicker">Today</span>
              <h1>Student Attendance</h1>
              <p>Mark attendance for students assigned to you.</p>
            </div>
            <button className="hw-icon-btn attendance-refresh" type="button" onClick={loadAttendance} disabled={loading} aria-label="Refresh">
              <FaSyncAlt />
            </button>
          </header>

          {alert && <Alert variant={alert.variant}>{alert.message}</Alert>}

          <section className="attendance-filter-card">
            <Form.Group>
              <Form.Label>Class</Form.Label>
              <Form.Select value={classId} onChange={handleClassChange}>
                <option value="">Select class</option>
                {classes.map((classItem) => <option key={classItem.clsid} value={classItem.clsid}>{classItem.clsnm}</option>)}
              </Form.Select>
            </Form.Group>
            <Form.Group>
              <Form.Label>Section</Form.Label>
              <Form.Select value={sectionId} onChange={handleSectionChange} disabled={!classId}>
                <option value="">Select section</option>
                {sections.map((section) => <option key={section.secid} value={section.secid}>{section.secnm}</option>)}
              </Form.Select>
            </Form.Group>
            <button className="attendance-check" type="button" onClick={loadAttendance} disabled={loading || !classId || !sectionId}>
              {loading ? <Spinner as="span" animation="border" size="sm" /> : <FaSearch />} Check
            </button>
          </section>

          {loading ? (
            <div className="attendance-empty"><Spinner animation="border" /><span>Loading attendance...</span></div>
          ) : !hasSearched ? (
            <div className="attendance-empty"><FaCalendarCheck /><span>Select class and section, then tap Check.</span></div>
          ) : students.length === 0 ? (
            <div className="attendance-empty"><FaCalendarCheck /><span>No students found for attendance today.</span></div>
          ) : (
            <div className="attendance-list">
              {students.map((student) => (
                <article className="attendance-card" key={student.atndncid || student.stdid}>
                  <div className="attendance-student-copy">
                    <strong>{student.stdnm || `Student ${student.stdid}`}</strong>
                    <span>{[student.clsnm, student.secnm].filter(Boolean).join(' • ')}</span>
                  </div>
                  <select
                    value={statuses[student.stdid] || ''}
                    onChange={(event) => setStatuses((current) => ({ ...current, [student.stdid]: event.target.value }))}
                    aria-label={`Attendance for ${student.stdnm}`}
                  >
                    <option value="" disabled>Select attendance</option>
                    {attendanceOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
                  </select>
                </article>
              ))}
            </div>
          )}

          {students.length > 0 && (
            <button className="attendance-save" type="button" onClick={saveAttendance} disabled={saving}>
              {saving ? <><Spinner as="span" animation="border" size="sm" /> Saving...</> : 'Save Attendance'}
            </button>
          )}
        </div>
      </div>
    </Layout>
  );
}

function AttendancePage() {
  const { stateAuth } = useContext(AuthContext);
  return String(stateAuth?.user?.typ || '').toUpperCase() === 'STUDENT'
    ? <StudentAttendanceSummary />
    : <StaffAttendancePage />;
}

export default AttendancePage;
